  return (
    <section className="current-dashboard" aria-label={dashboard.sourceLabel}>
      <div>
        <Text className="eyebrow">Источник показателя</Text>
        <Title level={2}>{dashboard.sourceLabel}</Title>
      </div>
      <Card className="metric-card">
        <Statistic
